def load_json(path: Path):
    return json.loads(path.read_text(encoding="utf-8"))

def safe_id(label: str) -> str:
    return "legacy-" + "-".join("".join(c.lower() if c.isalnum() else " " for c in label).split())

def triage_existing_inventory(domain_structure: dict, provenance: dict, computational: dict, guidance: dict):
    expected = {label: family for family, labels in FAMILY_LABELS.items() for label in labels}
    source_by_id = {s["id"]:s for s in SOURCES}
    items = []
    for label, record in provenance["foundation_skills"].items():
        family = expected.get(label)
        if family is None:
            raise ValueError(f"No explicit disposition family for canonical D078 label: {label}")
        disposition, rationale = FAMILY_DECISIONS[family]
        items.append({
            "item_id": safe_id(label),
            "canonical_label": label,
            "canonical_inventory": "data/career-mapping/domain_skill_provenance.json:D078.foundation_skills",
            "canonical_owner_flag": record.get("ownership"),
            "canonical_visibility_flag": record.get("student_visibility"),
            "role_aggregate_count_metadata_only": record.get("role_count"),
            "source_tags_in_inventory": record.get("sources", []),
            "disposition_family": family,
            "disposition": disposition,
            "decision_rationale": rationale,
            "possible_area_support_if_task_fits": area_support(label, family),
            "evidence": [{"source_id":src,"exact_locator":source_by_id[src]["locator"]} for src in evidence_for_family(family)],
            "not_role_audit": True,
        })
    if len(items) != 137:
        raise ValueError(f"Expected 137 source inventory labels, found {len(items)}")
    current = domain_structure["D078"]
    canonical_aggregate = []
    for skill in current.get("foundation_skills", []):
        label = skill["skill"]
        family = expected.get(label)
        if family is None:
            raise ValueError(f"No explicit disposition family for domain_structure D078 label: {label}")
        disposition, rationale = FAMILY_DECISIONS[family]
        canonical_aggregate.append({
            "item_id":safe_id(label)+"-domain-aggregate",
            "canonical_label":label,
            "canonical_inventory":"data/career-mapping/domain_structure.json:D078.foundation_skills",
            "role_aggregate_count_metadata_only":skill.get("n"),
            "prevalence_metadata_only":skill.get("prevalence"),
            "disposition_family":family,
            "disposition":disposition,
            "decision_rationale":rationale,
            "possible_area_support_if_task_fits":area_support(label, family),
            "evidence":[{"source_id":src,"exact_locator":source_by_id[src]["locator"]} for src in evidence_for_family(family)],
            "not_role_audit":True,
        })
    if len(canonical_aggregate)!=30:
        raise ValueError(f"Expected 30 domain_structure summary labels, found {len(canonical_aggregate)}")
    method_items = [x for x in computational.get("methods", []) if x.get("domain_id") == "D078"]
    known_method_sources = {
        "https://sociology.cornell.edu/research/computational-social-science":"cornell_css",
        "https://www.asanet.org/wp-content/uploads/section_calls_for_submissions.pdf":"national_academies_social_models",
        "global_esco":"esco_skills_classification",
    }
    for method in method_items:
        method["review_disposition"] = "specialist_method_option_not_domain_wide"
        method["source_record_locator"] = "data/career-mapping/computational_method_evidence.json:methods[]; exact label/description in record"
        method["evidence_status"] = "independently_corroborated" if known_method_sources.get(method.get("source")) else "source_not_independently_verified_or_not_opened"
        method["external_source_id"] = known_method_sources.get(method.get("source"))
        method["learning_link_status"] = "direct course link verified for computational social science; individual method claims remain separately scoped"
        method["note"] = "Discovery record only. Social network analysis occurs twice across area codes and is one unique method. The original ASA source URL for computational models returned 403, but the broad method family is independently corroborated by the National Academies chapter. Agent-based modelling is separately verified as a specialist method, not a domain-wide requirement. Game theory is explicitly marked not inherently computational. The Edinburgh course supports the computational-method family but does not independently validate every inventory label."
    existing_clusters = []
    for group in current.get("subgroups", []):
        for skill in group.get("cluster_skills", []):
            if skill == "social network analysis":
                disp, note, evidence = "area_specific_method_option", "A recognized method for studying relations among people/organizations; only when network ties answer the question.", [{"source_id":"cornell_css","exact_locator":source_by_id["cornell_css"]["locator"]}]
            elif skill == "game theory":
                disp, note, evidence = "discipline_specific_knowledge_not_inherently_computational", "Mathematical models of strategic decisions; may suit selected economics/political-science questions but is not a general social-research prerequisite.", [{"source_id":"esco_game_theory","exact_locator":source_by_id["esco_game_theory"]["locator"]}]
            elif skill == "execute analytical mathematical calculations":
                disp, note, evidence = "quantitative_specialist_option", "Mathematical calculations support some quantitative/computational analyses; no evidence makes them a shared foundation for all D078 paths.", [{"source_id":"esrc_training","exact_locator":source_by_id["esrc_training"]["locator"]},{"source_id":"ucsd_css_curriculum","exact_locator":source_by_id["ucsd_css_curriculum"]["locator"]}]
            else:
                disp, note, evidence = "context_specific_language_capability_not_domain_requirement", "Language choice can matter for a specific population, source or field site; no evidence establishes a particular language or multilingualism as universal D078 content.", [{"source_id":"unesco_definition","exact_locator":source_by_id["unesco_definition"]["locator"]}]
            existing_clusters.append({"legacy_subgroup_label":group.get("label"),"taxonomy_state":"retired_legacy_evidence_only_not_a_current_area","label":skill,"canonical_inventory":"data/career-mapping/domain_structure.json:D078.subgroups[].cluster_skills[]","disposition":disp,"note":note,"evidence":evidence,"learning_link_status":"not assessed as a display item; do not promote without item-specific link and checkpoint review"})
    return items, canonical_aggregate, method_items, existing_clusters

